package com.vandorlabs.neoforge.furniture;

import com.vandorlabs.neoforge.plate.*;
import com.vandorlabs.neoforge.seating.*;
import com.vandorlabs.neoforge.surface.*;
import java.util.*;
import net.minecraft.core.BlockPos;
import net.minecraft.core.component.DataComponents;
import net.minecraft.nbt.*;
import net.minecraft.network.chat.Component;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.item.*;
import net.minecraft.world.item.component.*;

/** Detached item-to-tile-to-item ownership, before any world save can mask component loss. */
public final class NativeFurnitureItemChecks {
    private static int checks;
    private static final List<String> failures=new ArrayList<>();
    private static void need(boolean yes,String why){checks++;if(!yes)failures.add(why);}
    private static ItemStack source(Item item){var stack=new ItemStack(item);stack.set(DataComponents.CONTAINER,ItemContainerContents.fromItems(List.of(new ItemStack(Items.DIAMOND,37))));stack.set(DataComponents.CUSTOM_NAME,Component.literal("Exact furniture owner"));return stack;}
    private static void same(ItemStack source,ItemStack result,String kind){need(Objects.equals(source.get(DataComponents.CONTAINER),result.get(DataComponents.CONTAINER)),kind+" 37 diamonds retained before save");need(Objects.equals(source.get(DataComponents.CUSTOM_NAME),result.get(DataComponents.CUSTOM_NAME)),kind+" custom name retained before save");}
    public static void run(ServerLevel level){checks=0;failures.clear();
        for(var kind:NativeSeatKind.values()){var state=NativeSeatBindings.BLOCKS.get(kind).defaultBlockState();var input=source(NativeSeatBindings.ITEMS.get(kind));var tile=new NativeChairEntity(BlockPos.ZERO,state);tile.applyComponentsFromItemStack(input);need(tile.components().has(DataComponents.CONTAINER),kind+" inherited component installed");var result=new ItemStack(input.getItem());tile.writeItem(result);same(input,result,kind.toString());var next=new NativeChairEntity(BlockPos.ZERO,state);next.applyComponentsFromItemStack(result);need(Objects.equals(tile.collectComponents(),next.collectComponents()),kind+" component/config round trip");}
        var state=NativePlateBindings.BLOCK.defaultBlockState();var input=source(state.getBlock().asItem());var tile=new NativePlateEntity(BlockPos.ZERO,state);tile.applyComponentsFromItemStack(input);need(tile.components().has(DataComponents.CONTAINER),"plate inherited component installed");var result=new ItemStack(input.getItem());tile.writeItem(result);same(input,result,"plate");var next=new NativePlateEntity(BlockPos.ZERO,state);next.applyComponentsFromItemStack(result);need(Objects.equals(tile.collectComponents(),next.collectComponents()),"plate component/config round trip");
        for(int variant=0;variant<3;variant++){var raw=new CompoundTag();raw.putString("Unrelated","retain exactly");if(variant==0){var settings=new CompoundTag();settings.putInt(com.vandorlabs.persistence.PressurePlateSettings.MODE,99);raw.put(NativePlateEntity.ITEM_SETTINGS,settings);}else raw.putString(variant==1?NativePlateEntity.ITEM_SETTINGS:"NativePlateRetained","wrong type");var stack=source(input.getItem());stack.set(DataComponents.CUSTOM_DATA,CustomData.of(raw));var bad=new NativePlateEntity(BlockPos.ZERO,state);bad.applyComponentsFromItemStack(stack);need(bad.inert(),"plate malformed item "+variant+" inert");var carrier=new ItemStack(input.getItem());bad.writeItem(carrier);need(carrier.get(DataComponents.CUSTOM_DATA)!=null&&carrier.get(DataComponents.CUSTOM_DATA).copyTag().getCompound("NativePlateRetained").equals(raw),"plate malformed item "+variant+" exact retained carrier");var cold=new NativePlateEntity(BlockPos.ZERO,state);cold.applyComponentsFromItemStack(carrier);var repeated=new ItemStack(input.getItem());cold.writeItem(repeated);need(cold.inert()&&Objects.equals(carrier.get(DataComponents.CUSTOM_DATA),repeated.get(DataComponents.CUSTOM_DATA)),"plate malformed item "+variant+" repeated retention");same(stack,carrier,"malformed plate "+variant);var saved=bad.saveWithoutMetadata(level.registryAccess());var loaded=new NativePlateEntity(BlockPos.ZERO,state);loaded.loadWithComponents(saved,level.registryAccess());var recovered=new ItemStack(input.getItem());loaded.writeItem(recovered);need(loaded.inert()&&Objects.equals(carrier.get(DataComponents.CUSTOM_DATA),recovered.get(DataComponents.CUSTOM_DATA)),"plate malformed item "+variant+" cold inert/raw carrier");same(stack,recovered,"cold malformed plate "+variant);}
        for(var kind:NativeSeatKind.values()){var seatState=NativeSeatBindings.BLOCKS.get(kind).defaultBlockState();var raw=new CompoundTag();raw.putString(NativeChairEntity.ITEM_SETTINGS,"wrong type");raw.putString("Unrelated","retain exactly");var stack=source(NativeSeatBindings.ITEMS.get(kind));stack.set(DataComponents.CUSTOM_DATA,CustomData.of(raw));var bad=new NativeChairEntity(BlockPos.ZERO,seatState);bad.applyComponentsFromItemStack(stack);need(bad.inert(),kind+" malformed item inert");var saved=bad.saveWithoutMetadata(level.registryAccess());var loaded=new NativeChairEntity(BlockPos.ZERO,seatState);loaded.loadWithComponents(saved,level.registryAccess());var resultItem=new ItemStack(stack.getItem());loaded.writeItem(resultItem);need(loaded.inert()&&resultItem.get(DataComponents.CUSTOM_DATA).copyTag().getCompound("NativeChairRetained").equals(raw),kind+" cold malformed exact raw carrier");same(stack,resultItem,"cold malformed "+kind);}
        var at=new BlockPos(18360,120,18360);level.setChunkForced(at.getX()>>4,at.getZ()>>4,true);level.getChunkAt(at);var surfaceState=NativeSurfaceBindings.BLOCK.defaultBlockState();level.setBlock(at,surfaceState,3);var surface=(NativeSurfaceEntity)level.getBlockEntity(at);var surfaceInput=source(surfaceState.getBlock().asItem());var opaque=new CompoundTag();opaque.putInt("foreign:stored",37);surfaceInput.set(DataComponents.CUSTOM_DATA,CustomData.of(opaque));surface.applyComponentsFromItemStack(surfaceInput);var picked=NativeSurfaceBindings.BLOCK.getCloneItemStack(surfaceState,new net.minecraft.world.phys.BlockHitResult(net.minecraft.world.phys.Vec3.atCenterOf(at),net.minecraft.core.Direction.UP,at,false),level,at,null);same(surfaceInput,picked,"surface clone");need(picked.get(DataComponents.CUSTOM_DATA).copyTag().getInt("foreign:stored")==37,"surface clone retains unrelated custom data");var drops=net.minecraft.world.level.block.Block.getDrops(surfaceState,level,at,surface);need(drops.size()==1&&drops.get(0).getCount()==1,"surface one exact drop");if(drops.size()==1)same(surfaceInput,drops.get(0),"surface loot");level.removeBlock(at,false);
        if(!failures.isEmpty())throw new AssertionError("Furniture item ownership checks="+checks+" failures="+failures);
        System.out.println("[vandorlabs][furniture-items] PASS checks="+checks+" detached/noSave inherited37Diamonds/name/fourSeats/plate/surfaceCloneLoot/exactInertColdCarrier");
    }
    private NativeFurnitureItemChecks(){}
}
